INSERT INTO hud_hmis_validation_fy2026 (check_type, check_name, severity, description) VALUES
('Intra-file', 'MissingFile', 'CRITICAL (gates others)','A required HUD CSV file is absent from the uploaded ZIP archive.'),
('Intra-file', 'ExportFile', 'CRITICAL (gates others)','Export.csv must contain exactly one data row; flags files with more than one record.'),
('Intra-file', 'EnrollmentFile', 'WARNING','Enrollment.csv must contain at least one data row; flags an empty enrollment file.'),
('Intra-file', 'ExtraColumn', 'CRITICAL (gates others)','A file contains columns that are not defined for that file in the HUD filelist specification.'),
('Intra-file', 'PriorityColumn', 'CRITICAL (gates others)','A file is missing one or more expected priority (critical) columns; column names are case sensitive. (e.g.  Client.PersonalID, Client.DOB)'),
('Intra-file', 'NonPriorityColumn', 'CRITICAL (gates others)','A file is missing one or more expected non-priority (non-critical) columns; column names are case sensitive. (e.g. Client.FirstName, Enrollment.DateOfEngagement)'),
('Intra-file', 'NonNullableCriticalNull', 'ERROR','A required critical field that cannot be null contains null (missing) values. (e.g. Client.PersonalID, Enrollment.EntryDate)'),
('Intra-file', 'NonNullableCriticalBlank', 'ERROR','A required critical field that cannot be null contains blank or whitespace-only values. (e.g.  Client.PersonalID, Enrollment.EntryDate)'),
('Intra-file', 'NonNullableNonCriticalNull', 'ERROR','A non-critical field that cannot be null contains null (missing) values. (e.g. Client.SSNDataQuality, Enrollment.UserID)'),
('Intra-file', 'NonNullableNonCriticalBlank', 'ERROR','A non-critical field that cannot be null contains blank or whitespace-only values. (e.g.  Client.SSNDataQuality, Enrollment.UserID)'),
('Intra-file', 'UniqueCheck', 'ERROR','A field defined as a unique identifier contains duplicate values within its file. (e.g. Client.PersonalID, Enrollment.EnrollmentID)'),
('Intra-file', 'ForeignKey', 'ERROR','A foreign-key field references an ID that does not exist in the required parent file. (e.g.  Enrollment.PersonalID, Enrollment.ProjectID)'),
('Intra-file', 'OutOfRange', 'ERROR','A field with a HUD lookup list contains a value that is not a valid code for that list.'),
('Intra-file', 'ConditionalOutOfRange', 'ERROR','A field must hold a valid lookup value only when another field in the same file equals a given value. (e.g. Enrollment.RentalSubsidyType required when LivingSituation=435; Project.ProjectType required when ContinuumProject=1)'),
('Intra-file', 'ConditionalOutOfRangeWithGroup', 'ERROR','A field must hold a valid lookup value only when every condition in a group of same-file conditions is met. (e.g. Disabilities.TCellCountAvailable required when DisabilityType=8 AND DisabilityResponse=1; Project.ResidentialAffiliation required when ProjectType=13 AND RRHSubType=1)'),
('Intra-file', 'ConditionalOutOfRangeCrossFile', 'ERROR','A field must hold a valid lookup value only when a linked record in another file meets a condition. (e.g.  Inventory.Availability required when linked Project.ProjectType=0; Inventory.ESBedType required when linked Project.ProjectType=1)'),
('Intra-file', 'DateFormat', 'ERROR','A critical date field contains a value not in yyyy-mm-dd format. (e.g. Client.DOB, Enrollment.EntryDate)'),
('Intra-file', 'DateFormatNonPriority', 'ERROR','A non-critical date field contains a value not in yyyy-mm-dd format. (e.g.  Enrollment.DateOfEngagement, Exit.AftercareDate)'),
('Intra-file', 'DatetimeFormat', 'ERROR','A critical date-time field contains a value not in yyyy-mm-dd hh:mm:ss format. (e.g. Client.DateCreated, Enrollment.DateUpdated)'),
('Intra-file', 'DatetimeFormatNonPriority', 'ERROR','A non-critical date-time field contains a value not in yyyy-mm-dd hh:mm:ss format. (e.g.  Client.DateDeleted, Exit.DateDeleted)'),
('Intra-file', 'NumericFormat', 'ERROR','A numeric field contains a value that is not a valid number. (e.g. IncomeBenefits.TotalMonthlyIncome, Services.FAAmount)'),
('Intra-file', 'IntegerFormat', 'ERROR','A critical integer field contains a value that is not a valid whole number or is missing. (e.g.  Client.NameDataQuality, Enrollment.RelationshipToHoH)'),
('Intra-file', 'IntegerFormatNonPriority', 'WARNING','A non-critical integer field contains a value that is not a valid whole number or is missing. (e.g.  Client.SSNDataQuality, Client.Sex)'),
('Intra-file', 'CharacterFormat', 'ERROR','A character field contains a value longer than the maximum length defined for that field. (e.g.  Client.FirstName, Client.PersonalID)'),
('Intra-file', 'ProhibitedChars', 'CRITICAL (gates others)','A character column contains prohibited characters (<, >, [, ], {, }), which are treated as a structural blocker. (e.g. Client.FirstName, Project.ProjectName)'),
('Intra-file', 'ExportCSVVersion', 'WARNING','Export.CSVVersion does not contain the expected HUD CSV specification version (FY2026 by default).  (e.g. Export.CSVVersion)'),
('Intra-file', 'SubPopulationBedCount', 'WARNING','For residential projects, the sum of subpopulation bed counts (CH, Vet, Youth and other) does not equal BedInventory. (e.g. Inventory.BedInventory)'),
('Intra-file', 'ProjectOperatingEndDate', 'WARNING','A project with a null OperatingEndDate has all enrollments exited with the latest exit more than 30 days before the ExportDate. (e.g. Project.OperatingEndDate)'),
('Intra-file', 'MissingCoCAddress', 'WARNING','A non-VSP, non-tenant-scattered-site ProjectCoC record is missing Address1, City or State, or has an invalid ZIP. (e.g. ProjectCoC.Address1, ProjectCoC.ZIP)'),
('Intra-file', 'InventoryStartDateBeforeOperatingStart', 'WARNING','An Inventory InventoryStartDate is earlier than the linked project''s OperatingStartDate. (e.g.  Inventory.InventoryStartDate, Project.OperatingStartDate)'),
('Intra-file', 'InventoryEndDateValidation', 'WARNING','An InventoryEndDate is later than the project''s OperatingEndDate, or the inventory is open while the project has ended. (e.g. Inventory.InventoryEndDate, Project.OperatingEndDate)'),
('Intra-file', 'ActiveInventoryNoEnrollment', 'WARNING','A project has active non-overflow bed inventory but no enrollment overlapping the inventory start and end dates. (e.g. Inventory.InventoryStartDate)'),
('Intra-file', 'RRHProjectMissingRRHSubType', 'WARNING','A project with ProjectType 13 (Rapid Re-Housing) has no RRHSubType value. (e.g. Project.RRHSubType)'),
('Intra-file', 'VSPProjectHMISParticipating', 'WARNING','A project under a Victim Service Provider organization is reported as actively participating in HMIS (HMISParticipationType = 1). (e.g. Organization.VictimServiceProvider)'),
('Intra-file', 'ActiveHMISProjectNoEnrollments', 'WARNING','A project with active HMIS participation and active bed inventory has no enrollments during its combined operating and HMIS-participating period. (e.g. HMISParticipation.HMISParticipationType)'),
('Intra-file', 'OverlappingHMISParticipation', 'ERROR','A project has two or more HMISParticipation records whose participation periods overlap, treating a null end date as still active. (e.g. HMISParticipation.HMISParticipationStatusStartDate)'),
('Intra-file', 'OverlappingCEParticipation', 'ERROR','A project has two or more CEParticipation records whose participation periods overlap, treating a null end date as still active. (e.g. CEParticipation.CEParticipationStatusStartDate)'),
('Intra-file', 'RRHSOProjectWithInventory', 'WARNING','An RRH Services Only project (ProjectType 13, RRHSubType 1) has active bed inventory overlapping its operating period, which it should not have. (e.g. Project.RRHSubType)'),
('Intra-file', 'NBNESProjectNoEntryBedNight', 'WARNING','A night-by-night emergency shelter with HMIS participation has no enrollment with a bed-night service (RecordType 200) dated on the entry date. (e.g. Services.DateProvided)'),
('Intra-file', 'ProjectCoCMissingBedInventory', 'WARNING','A residential project''s ProjectCoC record has no matching active bed inventory record for the same CoCCode. (e.g. ProjectCoC.CoCCode, Inventory.CoCCode)'),
('Intra-file', 'UnitInventoryMoreThanBedInventory', 'WARNING','An Inventory record reports more units (UnitInventory) than beds (BedInventory). (e.g.  Inventory.UnitInventory, Inventory.BedInventory)'),
('Intra-file', 'VSPProjectWithEnrollment', 'WARNING','A project under a Victim Service Provider organization has client enrollments, which should not be reported. (e.g. Organization.VictimServiceProvider)'),
('Intra-file', 'ResidentialProjectHousingTypeNull', 'ERROR','A residential project (ES, TH, SH, PH types) has a null HousingType. (e.g. Project.HousingType)'),
('Intra-file', 'ResidentialProjectNoInventory', 'WARNING','A residential project has no matching Inventory record. (e.g. Project.ProjectID, Inventory.ProjectID)'),
('Intra-file', 'SeasonalInventoryInvalidEndDate', 'WARNING','A seasonal Inventory record (Availability = 2) has no end date or spans more than 365 days. (e.g.  Inventory.InventoryEndDate)'),
('Intra-file', 'EmergencyShelterBedTypeHousingTypeMismatch', 'ERROR','An emergency shelter project''s ESBedType is inconsistent with its HousingType (site-based needs facility or other beds; tenant-based needs vouchers). (e.g. Inventory.ESBedType, Project.HousingType)'),
('Intra-file', 'RaceNoneExclusivity', 'ERROR','RaceNone has a value while at least one race field equals 1; RaceNone should be populated only when all race fields are 0. (e.g. Client.RaceNone)'),
('Intra-file', 'RaceNoneCompleteness', 'ERROR','All race fields are 0 but RaceNone is null or 0, so no race response is recorded. (e.g. Client.RaceNone)'),
('Intra-file', 'VeteranStatusYearEnteredSeparatedInvalid', 'WARNING','For veterans, YearEnteredService or YearSeparated is not a valid 4-digit year between 1920 and the current year. (e.g. Client.YearEnteredService, Client.YearSeparated)'),
('Intra-file', 'LinkedClientCheck', 'ERROR','A child record (Exit, Disabilities, IncomeBenefits, Services and similar) has a PersonalID that differs from its linked Enrollment record. (e.g. Exit.PersonalID, Services.PersonalID)'),
('Intra-file', 'VeteranStatusNullFields', 'WARNING','For VeteranStatus = 1, MilitaryBranch, DischargeStatus or all war-era fields are null. (e.g.  Client.MilitaryBranch, Client.DischargeStatus)'),
('Intra-file', 'VeteranStatusDKRCodes', 'WARNING','For VeteranStatus = 1, DischargeStatus, MilitaryBranch or all war-era fields hold DKR/DNC codes (8, 9, 99). (e.g. Client.DischargeStatus, Client.MilitaryBranch)'),
('Intra-file', 'VeteranStatusNullFieldsNonVeteran', 'WARNING','VeteranStatus is not 1 but veteran-only fields such as service years, branch, discharge status or war-era flags are populated. (e.g. Client.YearEnteredService, Client.MilitaryBranch)'),
('Intra-file', 'ProjectCoCCodeCheck', 'CRITICAL (gates others)','A ProjectCoC CoCCode is not in the allowed CoC list supplied for the export; skipped when no list is given. (e.g. ProjectCoC.CoCCode)'),
('Intra-file', 'DuplicateEnrollment', 'ERROR','Multiple Enrollment records share the same PersonalID, ProjectID and EntryDate. (e.g.  Enrollment.PersonalID, Enrollment.EntryDate)'),
('Intra-file', 'ClientFieldsDKRDNC', 'WARNING','NameDataQuality, DOBDataQuality, SSNDataQuality or RaceNone holds a Don''t Know, Refused or Data Not Collected code (8, 9, 99). (e.g. Client.NameDataQuality, Client.SSNDataQuality)'),
('Intra-file', 'ClientDOBDataQuality', 'ERROR','DOB is missing although DOBDataQuality is 1 or 2, indicating a full or approximate DOB was collected.  (e.g. Client.DOB, Client.DOBDataQuality)'),
('Intra-file', 'ClientAgeAtEntryCheck', 'ERROR','Age at enrollment entry (EntryDate year minus DOB year) is negative or greater than 100. (e.g.  Client.DOB, Enrollment.EntryDate)'),
('Intra-file', 'VeteranStatusAdultClientDKRCodes', 'WARNING','An adult (age 18 or older, or unknown) has VeteranStatus of DKR or DNC (8, 9, 99). (e.g.  Client.VeteranStatus)'),
('Intra-file', 'HouseHoldIdInMultipleProjects', 'WARNING','A HouseholdID is associated with enrollments in more than one project. (e.g. Enrollment.HouseholdID, Enrollment.ProjectID)'),
('Intra-file', 'HOHAdultMissingDateHomelessnessBegan', 'WARNING','For head of household or adults, LOSUnderThreshold=1 and PreviousStreetESSH=1 but DateToStreetESSH is null. (e.g. Enrollment.DateToStreetESSH)'),
('Intra-file', 'HOHAdultMissingESSHStayIndicator', 'WARNING','For head of household or adults entering on or after 2016-10-01, LOSUnderThreshold=1 but PreviousStreetESSH is null. (e.g. Enrollment.PreviousStreetESSH)'),
('Intra-file', 'HOHAdultLivingSituationMissing', 'WARNING','A head of household or adult enrollment has a null LivingSituation. (e.g. Enrollment.LivingSituation)'),
('Intra-file', 'HOHAdultLengthOfStayMissing', 'WARNING','A head of household or adult enrollment has a null LengthOfStay. (e.g. Enrollment.LengthOfStay)'),
('Intra-file', 'HOHAdultLivingSituationDKRDNC', 'WARNING','A head of household or adult enrollment has LivingSituation coded DKR or DNC (8, 9, 99). (e.g.  Enrollment.LivingSituation)'),
('Intra-file', 'HOHAdultLengthOfStayDKRDNC', 'WARNING','A head of household or adult enrollment has LengthOfStay coded DKR or DNC (8, 9, 99). (e.g.  Enrollment.LengthOfStay)'),
('Intra-file', 'HOHAdultMonthsHomelessDKRDNC', 'WARNING','A head of household or adult enrollment has MonthsHomelessPastThreeYears coded DKR or DNC (8, 9, 99). (e.g. Enrollment.MonthsHomelessPastThreeYears)'),
('Intra-file', 'HOHAdultTimesHomelessDKRDNC', 'WARNING','A head of household or adult enrollment has TimesHomelessPastThreeYears coded DKR or DNC (8, 9, 99). (e.g. Enrollment.TimesHomelessPastThreeYears)'),
('Intra-file', 'HOHAdultDisablingConditionDKRDNC', 'WARNING','A head of household or adult enrollment has DisablingCondition coded DKR or DNC (8, 9, 99). (e.g.  Enrollment.DisablingCondition)'),
('Intra-file', 'HOHAdultMissingTimes', 'WARNING','For head of household or adults in ES, SO or SH projects, TimesHomelessPastThreeYears or MonthsHomelessPastThreeYears is null. (e.g. Enrollment.TimesHomelessPastThreeYears)'),
('Intra-file', 'DateToStreetESSHAfterEntryDate', 'WARNING','The date homelessness began (DateToStreetESSH) falls after the enrollment EntryDate. (e.g.  Enrollment.DateToStreetESSH, Enrollment.EntryDate)'),
('Intra-file', 'MonthsHomelessPastThreeYearsInDKRDNC', 'WARNING','TimesHomelessPastThreeYears = 1 but MonthsHomelessPastThreeYears holds a DKR or DNC code (8, 9, 99). (e.g. Enrollment.MonthsHomelessPastThreeYears)'),
('Intra-file', 'MonthsHomelessMismatch', 'WARNING','TimesHomelessPastThreeYears = 1 but the calendar months from DateToStreetESSH to EntryDate do not match MonthsHomelessPastThreeYears. (e.g. Enrollment.MonthsHomelessPastThreeYears)'),
('Intra-file', 'HomelessOver3YearsInconsistent', 'WARNING','DateToStreetESSH is over 36 months before EntryDate but TimesHomelessPastThreeYears is not 1 or MonthsHomelessPastThreeYears is below 112. (e.g. Enrollment.DateToStreetESSH)'),
('Intra-file', 'MissingLivingSituationHomelessnessHistory', 'WARNING','For adults and heads of household in TH, PSH, SSO, HP or RRH, a qualifying LivingSituation and LengthOfStay combination lacks required homelessness history fields. (e.g.  Enrollment.LOSUnderThreshold)'),
('Intra-file', 'ConflictingIncomeAtEntry', 'ERROR','At project entry (DataCollectionStage = 1), IncomeFromAnySource conflicts with the individual income source fields. (e.g. IncomeBenefits.IncomeFromAnySource)'),
('Intra-file', 'AdultMissingIncomeAtExit', 'WARNING','An exited adult enrollment in an income-collecting project lacks an exit-stage (DataCollectionStage = 3) IncomeBenefits record with IncomeFromAnySource populated. (e.g.  IncomeBenefits.IncomeFromAnySource)'),
('Intra-file', 'ConflictingIncomeAtExit', 'ERROR','At project exit (DataCollectionStage = 3), IncomeFromAnySource conflicts with the individual income source fields. (e.g. IncomeBenefits.IncomeFromAnySource)'),
('Intra-file', 'AdultMissingIncomeAtEntry', 'WARNING','An adult enrollment in an income-collecting project lacks an entry-stage (DataCollectionStage = 1) IncomeBenefits record with IncomeFromAnySource populated. (e.g.  IncomeBenefits.IncomeFromAnySource)'),
('Intra-file', 'ExitBeforeEntryDate', 'ERROR','An Exit record''s ExitDate is earlier than the enrollment''s EntryDate. (e.g. Exit.ExitDate, Enrollment.EntryDate)'),
('Intra-file', 'EntryAfterDateCreated', 'WARNING','An enrollment EntryDate is later than its DateCreated; PSH and OPH projects before 2017-10-01 are excused. (e.g. Enrollment.EntryDate, Enrollment.DateCreated)'),
('Intra-file', 'ExitDestinationDKRDNC', 'WARNING','An Exit Destination is DKR (8, 9), DNC (99) or 30 (no exit interview completed). (e.g. Exit.Destination)'),
('Intra-file', 'FutureExitDate', 'ERROR','An Exit record''s ExitDate is later than the export''s ExportDate. (e.g. Exit.ExitDate, Export.ExportDate)'),
('Intra-file', 'SSVFMissingPercentAMI', 'ERROR','A head of household enrollment in an SSVF project (ProjectType 12 or Funder 33) has a null PercentAMI.  (e.g. Enrollment.PercentAMI)'),
('Intra-file', 'SSVFPercentAMIDNC', 'WARNING','A head of household enrollment in an SSVF project (ProjectType 12 or Funder 33) has PercentAMI = 99 (Data Not Collected). (e.g. Enrollment.PercentAMI)'),
('Intra-file', 'SSVFMissingVAMCStation', 'ERROR','A head of household enrollment in an SSVF project (ProjectType 12 or Funder 33) has a null or blank VAMCStation. (e.g. Enrollment.VAMCStation)'),
('Intra-file', 'DataCollectionStageExitMissingExitData', 'ERROR','An IncomeBenefits, EmploymentEducation, HealthAndDV or Disabilities record has DataCollectionStage = 3 but the enrollment has no Exit record. (e.g.  IncomeBenefits.DataCollectionStage)'),
('Intra-file', 'DataCollectionStageAnnualOutOfWindow', 'WARNING','An annual assessment (DataCollectionStage = 5) has an InformationDate more than 30 days from every enrollment anniversary. (e.g. IncomeBenefits.InformationDate, Disabilities.InformationDate)'),
('Intra-file', 'YouthEduStatusInfoDateBeforeEntry', 'WARNING','A YouthEducationStatus InformationDate is earlier than the enrollment EntryDate. (e.g.  YouthEducationStatus.InformationDate)'),
('Intra-file', 'YouthEduStatusInfoDateAfterExportEnd', 'WARNING','A YouthEducationStatus InformationDate is more than 90 days after the export''s ExportEndDate. (e.g.  YouthEducationStatus.InformationDate)'),
('Intra-file', 'EventDateOutsideEnrollment', 'WARNING','An Event EventDate is before the enrollment EntryDate or after the ExitDate or the export''s ExportEndDate. (e.g. Event.EventDate)'),
('Intra-file', 'InvalidMoveInDate', 'ERROR','A permanent housing enrollment has a MoveInDate before its EntryDate or after its ExitDate. (e.g.  Enrollment.MoveInDate)'),
('Intra-file', 'EnrollmentOverlap', 'WARNING','An enrollment''s active period overlaps another enrollment for the same client in a residential project (dual enrollment). (e.g. Enrollment.EntryDate, Exit.ExitDate)'),
('Intra-file', 'EnrollmentAfterOperatingPeriod', 'ERROR','An enrollment starts after the project''s OperatingEndDate, which has already passed. (e.g.  Enrollment.EntryDate, Project.OperatingEndDate)'),
('Intra-file', 'EnrollmentCrossesOperatingStart', 'ERROR','An enrollment begins before the project''s OperatingStartDate and remains active past it without exceeding the OperatingEndDate. (e.g. Enrollment.EntryDate, Project.OperatingStartDate)'),
('Intra-file', 'EnrollmentBeforeOperatingPeriod', 'ERROR','An enrollment''s ExitDate is before the project''s OperatingStartDate; open enrollments never match.  (e.g. Exit.ExitDate, Project.OperatingStartDate)'),
('Intra-file', 'EnrollmentCrossesOperatingEnd', 'ERROR','An enrollment begins within the project''s operating period and remains active after the OperatingEndDate. (e.g. Enrollment.EntryDate, Project.OperatingEndDate)'),
('Intra-file', 'EnrollmentBeforeHmisParticipatingPeriod', 'WARNING','An enrollment ends before the project''s HMISParticipationStatusStartDate; open enrollments never match. (e.g. Exit.ExitDate, HMISParticipation.HMISParticipationStatusStartDate)'),
('Intra-file', 'EnrollmentCrossesHmisParticipationPeriod', 'ERROR','An enrollment begins before the HMIS participation start date and is still active after the participation end date. (e.g. Enrollment.EntryDate, HMISParticipation.HMISParticipationStatusEndDate)'),
('Intra-file', 'EnrollmentCrossesHmisParticipatingStart', 'WARNING','An enrollment begins before the HMIS participation start date and remains active past it without exceeding the end date. (e.g. Enrollment.EntryDate, HMISParticipation.HMISParticipationStatusStartDate)'),
('Intra-file', 'EnrollmentCrossesHmisParticipatingEnd', 'WARNING','An enrollment begins after the HMIS participation start date and remains active after the participation end date. (e.g. Enrollment.EntryDate, HMISParticipation.HMISParticipationStatusEndDate)'),
('Intra-file', 'EnrollmentAfterHmisParticipatingPeriod', 'ERROR','An enrollment''s EntryDate is after the project''s HMISParticipationStatusEndDate. (e.g.  Enrollment.EntryDate, HMISParticipation.HMISParticipationStatusEndDate)'),
('Cross-file', 'Semantic Duplicate: IncomeBenefits', 'WARNING','Multiple IncomeBenefits records share the same EnrollmentID, data collection stage and InformationDate but have different IncomeBenefitsIDs, within one source system.'),
('Cross-file', 'Net New Projects', 'WARNING (Notify Admins)','Flags Project records created for the first time in this import batch, so new projects can be reviewed before use.'),
('Cross-file', 'Net New Organizations', 'WARNING (Notify Admins)','Flags Organization records created for the first time in this import batch, so new organizations can be reviewed.'),
('Cross-file', 'Name Change Organizations', 'WARNING (Notify Admins)','Flags Organization records updated in this batch whose OrganizationName differs from the name already registered for that OrganizationID.'),
('Cross-file', 'ProjectCoC CoCCode mismatch', 'ERROR','Flags newly created ProjectCoC records whose CoCCode differs from the expected CoC code (currently hard-coded as NY-600).'),
('Cross-file', 'ProjectCoC ProjectID duplicates', 'WARNING (Notify Admins)','Flags ProjectIDs having more than one ProjectCoC record, regardless of CoCCode values.'),
('Cross-file', 'Missing Enrollment CoC for Head of Household', 'ERROR','Flags head of household enrollments changed in this batch whose EnrollmentCoC is null.'),
('Cross-file', 'Household with No Head of Household', 'ERROR','Flags households touched by this batch where no active member has RelationshipToHoH = 1 (Self/head of household).'),
('Cross-file', 'Household with Multiple Heads of Household', 'ERROR','Flags households touched by this batch where more than one active member has RelationshipToHoH = 1 (head of household).'),
('Cross-file', 'Children-Only Household', 'WARNING','Flags households touched by this batch where the oldest member''s age at enrollment is known and under 12.'),
('Cross-file', 'Missing Relationship to HoH', 'ERROR','Flags active enrollments with RelationshipToHoH = 99 (Data Not Collected) in households that already have a valid head of household.');
