DROP TABLE IF EXISTS hud_hmis_validation_fy2026;
CREATE TABLE hud_hmis_validation_fy2026 (
    rec_id       INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- Creates SEQUENCE: hud_hmis_validation_fy2026_rec_id_seq
    -- rec_id    INT IDENTITY(1,1) PRIMARY KEY,
    check_type   VARCHAR(80) NOT NULL,
    check_name   VARCHAR(80) UNIQUE NOT NULL,
    severity     VARCHAR(80) NOT NULL,
    description  TEXT NOT NULL,
    gates_others CHAR(1) DEFAULT 'N' NOT NULL,
    active       CHAR(1) DEFAULT 'Y' NOT NULL
);

COMMENT ON TABLE hud_hmis_validation_fy2026 IS
'FileCheck (Intra-file) and Import Validation Schema (Cross-file) Checks Items marked with "gates others" stop the processing of other checks because files or fields are incomplete, or the ability to load and check data is compromised.  Any CRITICAL or ERROR stops the import to the CWInsights warehouse.  Warnings allow data to load in the warehouse and transfer to ClientTrack UNLESS marked with "Notify Admins" which pause the CT transfer for the affected SourceSystem.  Last Update: 2026-11-02.';

